    @Transactional
    public Sheet lockForNumbering(String id) {
        return sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
    }

    /**
     * Change the sheet's today; it has no audit line of its own. With grace days set, the open periods
     * past them are closed first, then the figures it moves are audited.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        if (sheet.getGraceDays() != null) periods.getObject().autoClose(id, user, today, sheet.getGraceDays());
        rollup.recordChanges(id, user, before);
        return sheet;
    }

    /** Archive the sheet, as a steward (or one acting for a steward); anyone else is refused. */
    @Transactional
    public Sheet archive(String id, String user) {
        Sheet sheet = sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
        if (sheet.isArchived()) throw new SheetArchivedException();
        if (settings.getObject().roleOf(id, user) != Role.STEWARD) throw new SheetArchiveRefusedException();
        sheet.archive();
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return sheet;
    }
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in list order: newest first, a moved claim as the newest when it moved. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** The next place in the claims' list, after every claim added or moved so far. */
    @Query(value = "select next value for claim_listed_seq", nativeQuery = true)
    long nextListed();

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    /**
     * The last place given in a period's numbering on the sheet (empty name: in no period), counting those
     * given up by claims re-dated out of it; 0 if none.
     */
    @Query(value = "select coalesce(max(s), 0) from (select number_seq s from claim where sheet_id = :sheetId"
            + " and number_period = :period union all select number_seq s from claim_number_retired"
            + " where sheet_id = :sheetId and number_period = :period) n", nativeQuery = true)
    int lastNumberWithin(String sheetId, String period);

    /** Give up a place in a period's numbering on the sheet, so it is never given again. */
    @Modifying
    @Query(value = "insert into claim_number_retired (sheet_id, number_period, number_seq)"
            + " values (:sheetId, :period, :seq)", nativeQuery = true)
    void retireNumberWithin(String sheetId, String period, int seq);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);
}
-- A place in a period's numbering given up by a claim re-dated into another period: never given again.
CREATE TABLE claim_number_retired (
    sheet_id VARCHAR(100) NOT NULL,
    number_period VARCHAR(200) NOT NULL,
    number_seq INT NOT NULL,
    PRIMARY KEY (sheet_id, number_period, number_seq)
);

